def Dfs(G, v, n, visited):
    all_visited = True

    for i in range(n):
      if visited[i] == False:
        all_visited = False

    if all_visited:
        return 1

    ret = 0

    for i in range(n):
        if not G[v][i]:
            continue
        if visited[i]:
            continue
        visited[i] = True
        ret += Dfs(G, i, n, visited)
        visited[i] = False

    return ret


