      self.__N = n
      self.nodes = [None] * n
      self.edges = [{} for _ in range(n)]

    def add_node_info(self, v, **args): self.nodes[v] = self.__Node(**args)

    def add_edge(self, u, v, update=False, **args): 
      if not update and v in self.edges[u]: return 
      self.edges[u][v] = self.__Edge(**args)

