from collections import deque
from heapq import heappush, heappop
class Graph:
    def __init__(self, n_nodes, weighted=False) -> None:
        self.n_nodes = n_nodes
        self.weighted = weighted
        if weighted:
            self.adj_list = [[] for _ in range(self.n_nodes)]
        self.edge_list = [[] for _ in range(self.n_nodes)]
    def add_edge(self, u:int, v:int, w:int=1, directed=False) -> None:
        '''
        u: from
        v: to
        w: weight
        '''
        if self.weighted:
            self.adj_list[u].append((w, v))
        self.edge_list[u].append(v)
        if not directed:
            if self.weighted:
                self.adj_list[v].append((w, u))
            self.edge_list[v].append(u)
    def dfs(self, v:int) -> list:
        seen = [-1] * self.n_nodes
        prv = [None] * self.n_nodes
        subsize = [1] * self.n_nodes
        stack_front = deque()
        stack_back = deque()
        seen[v] = 0
        stack_front.append(v)
        while len(stack_front):
            u = stack_front.pop()
            for x in self.edge_list[u]:
                if seen[x] >= 0:
                    continue
                seen[x] = seen[u] + 1
                prv[x] = u
                stack_front.append(x)
                stack_back.append(x)
        while len(stack_back):
            u = stack_back.pop()
            subsize[prv[u]] += subsize[u] 
        return seen, subsize
    def bfs(self, v:int) -> list:
        seen = [-1] * self.n_nodes
        que = deque()
        seen[v] = 0
        que.append(v)
        while len(que):
            u = que.popleft()
            for x in self.edge_list[u]:
                if seen[x] >= 0:
                    continue
                seen[x] = seen[u] + 1
                que.append(x)
        return seen
    def dijkstra(self, s:int) -> list:
        distance = [INF] * self.n_nodes
        distance[s] = 0
        pque = []
        heappush(pque, (0, s))
        while pque:
            d, v = heappop(pque)
            if distance[v] < d:
                continue
            for cost, to in self.adj_list[v]:
                if distance[v] + cost < distance[to]:
                    distance[to] = distance[v] + cost
                    heappush(pque, (distance[to], to))
        return distance

