  return ans

def arr_pow(A, p, mod):
  res = np.eye(A.shape[0], dtype = np.int64)
  while p:
    if p & 1:
      res = np.dot(res, A) % mod
    A = np.dot(A, A) % mod
    p >>= 1
  return res

