# from typing import *
from collections import Counter


def j(n):
    if n < 400:
        return 1
    elif 400 <= n < 800:
        return 2
    elif 800 <= n < 1200:
        return 3
    elif 1200 <= n < 1600:
        return 4
    elif 1600 <= n < 2000:
        return 5
    elif 2000 <= n < 2400:
        return 6
    elif 2400 <= n < 2800:
        return 7
    elif 2800 <= n < 3200:
        return 8
    else:
        return 0


# def solve(N: int, a: List[int]) -> Tuple[int, int]:
def solve(N, a):
    li = []
    mi = 0
    xc = 0
    for i in range(N):
        li.append(j(a[i]))
    c = Counter(li)
    for k in c:
        if k:
            mi += 1
        else:
            xc += c[0]
    if mi == 0 and xc:
        return 1, xc
    mx = mi + xc
    return mi, mx


