class Algebra:
  class Modular(int):
    def __init__(self, n, mod=MOD):
      self.value = n
      self.mod = mod

    def __str__(self): return f'{self.value}'

    def __add__(self, other): 
      return self.__class__((self.value + other.value) % self.mod)
