  def cumprod(a, mod):
    l = len(a); sql = int(np.sqrt(l)+1)
    a = np.resize(a, sql**2).reshape(sql, sql)
    for i in range(sql-1): a[:, i+1] *= a[:, i]; a[:, i+1] %= mod
    for i in range(sql-1): a[i+1] *= a[i, -1]; a[i+1] %= mod
    return np.ravel(a)[:l]  

