    hq = [(0, s)]
    dist[s] = 0
    seen = [False] * (n + 1)
    while hq:
        v = heappop(hq)[1]
        seen[v] = True
        for to, cost in a[v]:
            if seen[to] == False and dist[v] + cost < dist[to]:
                dist[to] = dist[v] + cost
                heappush(hq, (dist[to], to))
    return dist


