from collections import deque


def bfs(G, s):
    Q = deque([])
    dist = [-1] * N
    dist[s] = 0
    for u in G[s]:
        dist[u] = 1
        Q.append(u)

    while Q:
        u = Q.popleft()
        for v in G[u]:
            if dist[v] != -1:
                continue
            dist[v] = dist[u] + 1
            Q.append(v)

    return dist


def relax(W, u, v, D, P):
    d = D[u] + W
    if d < D[v]:
        D[v], P[v] = d, u
        return True


