def sec14_2(G, distance):
    N = len(G)
    INF = math.pow(2, 60)
    cycle = False
    for i in range(2 * N + 1):
        for v in range(N):
            if distance == -INF:
                continue

            for c in G[v]:
                if distance[c[0]] > distance[v] + c[1]:
                    distance[c[0]] = distance[v] + c[1]
                    if c[0] == N - 1 and i == 2 * N:
                        cycle = True

    return -distance[-1], cycle

