class UnionFind:
    def __init__(self, val):
        self.par = [i for i in range(val)]
        self.siz = [1 for _ in range(val)]

    def root(self, x):
        if self.par[x] == x:
            return x
        self.par[x] = UnionFind.root(self, self.par[x])
        return self.par[x]

    def same(self, x, y):
        return UnionFind.root(self, x) == UnionFind.root(self, y)

    def unite(self, x, y):
        x = UnionFind.root(self, x)
        y = UnionFind.root(self, y)
        if x == y:
            return False
        if self.siz[x] < self.siz[y]:
            y, x = x, y
        self.par[y] = x
        self.siz[x] += self.siz[y]
        return True

    def size(self, x):
        return self.siz[UnionFind.root(self, x)]

