import numpy as np


class Kindergarten:
    def __init__(self, candy_amount_per_pack: List[int] = [1, 1, 1]):
        self.child_amount = 2
        self.np_candy_amount_per_pack = np.array(candy_amount_per_pack)

    def get_max_candy_amount(self):
        return max(self.np_candy_amount_per_pack)

    def get_other_candy_amount(self):
        other_amount_index = np.nonzero(self.np_candy_amount_per_pack != self.get_max_candy_amount())
        return self.np_candy_amount_per_pack[other_amount_index]

    def sum_other_candy_amount(self):
        return sum(self.get_other_candy_amount())

    def compare_max_and_other_amount(self):
        return self.sum_other_candy_amount() == self.get_max_candy_amount()

    def decide_share(self):
        if self.compare_max_and_other_amount():
            return 'Yes'
        else:
            return 'No'


