def solve(n: int, k: int, ab: List[List[int]]) -> int:
    memo = [0] * (pow(10, 5) + 1)
    for a, b in ab:
        memo[a] += b

    ans = 1
    count = 0
    while (count := count + memo[ans]) < k:
        ans += 1

    return ans


